/* ════════════════════════════════════════════════════════════
   netlify/functions/get-stats.js
   GET  /.netlify/functions/get-stats

   Email-only mode: no database is used.
   Returns a static response so the frontend counter
   stays silent without throwing errors.
   ════════════════════════════════════════════════════════════ */

'use strict';

exports.handler = async (event) => {
  if (event.httpMethod === 'OPTIONS') return { statusCode: 204 };
  if (event.httpMethod !== 'GET')
    return { statusCode: 405, body: JSON.stringify({ error: 'Method not allowed.' }) };

  /* No database — return null so frontend hides the counter */
  return {
    statusCode: 200,
    headers: {
      'Content-Type':               'application/json',
      'Access-Control-Allow-Origin': '*',
    },
    body: JSON.stringify({ count: null }),
  };
};
